"""Canonical character roster.

`arcs` maps a timeline point ("season" or "season.episode") to a storyline id from
world.STORYLINES; a character's location is the storyline's location. `aliases` are the
raw speaker names used in the script CSV. `stats` = (martial, diplomacy, intrigue,
learning, prowess) on a 0-20 scale. `orgs` = [(organisation, from, to|None)].
"""
from __future__ import annotations

from typing import Any


def C(cid: str, name: str, house: str | None, gender: str, tier: str, arcs: dict[str, str], *,
      aliases: tuple[str, ...] = (), death: str | None = None, killer: str | None = None,
      death_note: str = "", titles: tuple[str, ...] = (), culture: str = "", religion: str = "",
      stats: tuple[int, int, int, int, int] = (5, 5, 5, 5, 5), traits: tuple[str, ...] = (),
      summary: str = "", orgs: tuple[tuple[str, str, str | None], ...] = ()) -> dict[str, Any]:
    m, d, i, l, p = stats
    return {
        "id": cid, "name": name, "house": house, "gender": gender, "tier": tier, "arcs": arcs,
        "aliases": list(aliases), "death": death, "killer": killer, "death_note": death_note,
        "titles": list(titles), "culture": culture, "religion": religion,
        "stats": {"martial": m, "diplomacy": d, "intrigue": i, "learning": l, "prowess": p},
        "traits": list(traits), "summary": summary, "orgs": [list(o) for o in orgs],
    }


